// routeOwner is the lease owner tag the routing claims episode rows under —
// distinct from the workers' and the sweep's owners so a leaked lease is
// attributable in debugging (the reenrichOwner posture).
const routeOwner = "route"

// routeEpisodeTitles routes one successful SERIES run's ConvertResult
// episode-title entries onto the series' episode documents (episode-titles D5).
// The entries are the run's side-output: metadata wraps into the RUN document's
// namespace as usual, and each EpisodeTitle lands on the matching EPISODE
// document as sources.<plugin> plus the core's _provenance/_view stamps.
//
// The route is best-effort and fact-guarded: a series with no parsed season
// fact, a file-backed series (no episode documents), or an empty/unreadable
// episode set routes nothing. An episode is matched by its parse facts read
// namespace-agnostically (the display composer's episodeFacts rule — any
// sources namespace carrying BOTH season and episode as integers) against the
// series' own season fact read the same way: entry when episode-doc season ==
// series season AND episode number == entry.episode. No matching entry — the
// document is untouched; the season guard keeps a multi-season directory
// honest (another season's episode stays titleless instead of wrong).
//
// Writes are taken under THAT episode row's own lease (the workers' primitive,
// non-blocking — an unleased write could be resurrected by an in-flight
// episode worker's unconditional persistRow); lease-held rows are re-attempted
// once after reenrichRetryDelay (the sweep's one bounded retry pass) and a row
// that stays held keeps its document byte-identical. The episode's lifecycle
// status, the series run result, derivation, and Match are untouched: episode
// documents still never match at Match, and a routed namespace simply makes
// the episode's own (item, plugin) pair terminal through the unchanged
// has-namespace gate. No _stages entry is written (routing is not a chain
// run) — the stamps are the trace.
func (q *Queue) routeEpisodeTitles(ctx context.Context, sr store.Series, seriesDoc map[string]any, runs []sourceResult) {
	if len(runs) == 0 {
		return // no entries: routing does nothing
	}
	if backingOf(seriesDoc) != store.SeriesBackingDirectory {
		return // a file-backed series has no episode documents: the route is a no-op
	}
	season, ok := seriesSeason(seriesDoc)
	if !ok {
		return // no season fact: an entry can never match honestly
	}
	eps, err := q.deps.Store.QueryItemsBySeries(ctx, sr, store.SeriesBackingDirectory)
	if err != nil || len(eps) == 0 {
		return // best-effort: a read failure or an empty directory leaves every doc untouched
	}
	matches := make([]episodeTitleMatch, 0)
	for _, ep := range eps {
		s, e, ok := episodeFacts(decodeDoc(ep.Document))
		if !ok || s != season {
			continue // no parse facts, or another season: never matched
		}
		for _, run := range runs {
			if entry := matchEpisodeEntry(run.episodeTitles, e); entry != nil {
				matches = append(matches, episodeTitleMatch{itemID: ep.ID, run: run, entry: entry})
			}
		}
	}
	held := q.routePass(ctx, season, matches)
	if len(held) > 0 { // the one bounded retry pass (the reenrichRetryDelay posture)
		select {
		case <-ctx.Done():
			return
		case <-time.After(reenrichRetryDelay):
		}
		_ = q.routePass(ctx, season, held)
	}
}

// episodeTitleMatch is one planned episode-document write: the item row, the
// series run that produced the entries, and the entry its episode number
// matched.
type episodeTitleMatch struct {
	itemID string
	run    sourceResult
	entry  *metadatav1.EpisodeTitle
}

// routePass runs one routing write pass over the planned matches. Each write is
// taken under THAT episode row's own lease (non-blocking): the row is re-read
// under the lease, its facts re-checked against the plan, and the matched
// entry's namespace lands with its _provenance/_view stamps — built over the
// entry's own fields and the run's Convert hints and Match confidence, the
// same inputs the run document's stamps used. The episode's lifecycle status
// is never advanced. Returns the matches it could not attempt (a live lease
// held); a row that stays held keeps its document byte-identical (the row is
// never loaded before its lease is claimed).
func (q *Queue) routePass(ctx context.Context, season int64, matches []episodeTitleMatch) (held []episodeTitleMatch) {
	for _, m := range matches {
		if !q.leases.acquire(m.itemID, routeOwner, q.cfg.LeaseTTL) {
			held = append(held, m) // a worker owns the row — never write mid-flight
			continue
		}
		row, err := q.loadRow(ctx, m.itemID)
		if err != nil {
			q.leases.release(m.itemID)
			continue // the row is gone (or unreadable) between plan and write: nothing to route
		}
		doc := decodeDoc(row.doc)
		s, e, ok := episodeFacts(doc)
		entry := matchEpisodeEntry(m.run.episodeTitles, e)
		if !ok || s != season || entry == nil { // facts moved since the plan: nothing to write
			q.leases.release(m.itemID)
			continue
		}
		meta := entry.GetMetadata().AsMap()
		prov, view := buildProvenanceView(m.run.pluginID, meta, m.run.provHints, m.run.matchConfidence)
		applyContribution(doc, sourceResult{pluginID: m.run.pluginID, namespace: meta, provenance: prov, view: view})
		q.persistRow(ctx, row, row.status, doc)
		q.leases.release(m.itemID)
	}
	return held
}

// matchEpisodeEntry returns the first entry numbered e, or nil when the run
// contributes nothing for that episode number.
func matchEpisodeEntry(entries []*metadatav1.EpisodeTitle, e int64) *metadatav1.EpisodeTitle {
	for _, entry := range entries {
		if entry.GetEpisode() == e {
			return entry
		}
	}
	return nil
}

// backingOf reads the document's parsed.backing marker fact (the backing kind
// the serial scanner stamped — serials-library design.md §Interfaces §1).
// Empty when absent: an unmarked document is not a routable directory.
func backingOf(doc map[string]any) string {
	parsed, _ := doc["parsed"].(map[string]any)
	backing, _ := parsed["backing"].(string)
	return backing
}

// factNamespacesOrder lists sources' namespace keys in the fixed fact-read
// order, mirroring the display composer's rule (internal/api/display.go
// factNamespaces, display-naming D-3): the two verified writer namespaces
// first (serial-parser, then tv-parser), the rest sorted — so Go map iteration
// order never leaks into a routed write. A nil/empty sources map yields nil.
func factNamespacesOrder(sources map[string]any) []string {
	if len(sources) == 0 {
		return nil
	}
	rest := make([]string, 0, len(sources))
	for name := range sources {
		if name != "serial-parser" && name != "tv-parser" {
			rest = append(rest, name)
		}
	}
	sort.Strings(rest)
	ordered := make([]string, 0, len(rest)+2)
	if _, ok := sources["serial-parser"]; ok {
		ordered = append(ordered, "serial-parser")
	}
	if _, ok := sources["tv-parser"]; ok {
		ordered = append(ordered, "tv-parser")
	}
	return append(ordered, rest...)
}

// intFact reads an integral JSON number (the display composer's intField
// semantics — an integer-valued number). Documents carry numbers as float64
// after a store round-trip (decodeDoc) or a Struct.AsMap; the in-memory forms
// may carry json.Number or Go integers. A non-integral or non-numeric value
// never qualifies.
func intFact(v any) (int64, bool) {
	switch n := v.(type) {
	case float64:
		if n != math.Trunc(n) {
			return 0, false
		}
		return int64(n), true
	case json.Number:
		f, err := n.Float64()
		if err != nil || f != math.Trunc(f) {
			return 0, false
		}
		return int64(f), true
	case int64:
		return n, true
	case int:
		return int64(n), true
	}
	return 0, false
}

// episodeFacts reads the document's (season, episode) pair namespace-agnostically
// — the display composer's episodeFacts rule: any sources namespace carrying
// BOTH integers qualifies, walked in the fixed fact-read order (D-3). ok=false
// when no namespace carries the pair (a fresh episode document, or a namespace
// that names only one of the two).
func episodeFacts(doc map[string]any) (season, episode int64, ok bool) {
	sources, _ := doc["sources"].(map[string]any)
	for _, name := range factNamespacesOrder(sources) {
		ns, _ := sources[name].(map[string]any)
		s, sok := intFact(ns["season"])
		e, eok := intFact(ns["episode"])
		if sok && eok {
			return s, e, true
		}
	}
	return 0, 0, false
}

// seriesSeason reads the series document's own season fact the same way —
// namespace-agnostic, fixed fact-read order: the first namespace carrying an
// integer season wins. A series namespace carries no episode NUMBER (episodes
// is the synopsis count), so the composer's both-integers pair rule cannot
// apply to a series document.
func seriesSeason(doc map[string]any) (int64, bool) {
	sources, _ := doc["sources"].(map[string]any)
	for _, name := range factNamespacesOrder(sources) {
		ns, _ := sources[name].(map[string]any)
		if s, ok := intFact(ns["season"]); ok {
			return s, true
		}
	}
	return 0, false
}
